pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = (node_residual_cpu as f64 / node_capacity_cpu.max(1) as f64);
    let ram_norm = (node_residual_ram as f64 / node_capacity_ram.max(1) as f64);
    let imbalance_penalty = ((cpu_norm - ram_norm).abs() * 10.0).min(1.0);
    let lookahead_bonus = if next_job_cpu < cpu_norm && next_job_ram < ram_norm { 0.5 } else { 0.0 };
    let time_horizon_factor = (step_index as f64 / total_jobs as f64).powi(2);

    // Fine-grained residual fitting bonus
    let residual_fit_bonus = if node_residual_cpu > mean_cpu_residual || node_residual_ram > mean_ram_residual {
        -1.0
    } else {
        1.0
    };

    // Lookahead packing bonus
    let lookahead_pack_bonus = if next_job_cpu < cpu_norm && next_job_ram < ram_norm {
        (next_job_cpu as f64 / node_capacity_cpu.max(1) as f64 + next_job_ram as f64 / node_capacity_ram.max(1) as f64) * 0.5
    } else {
        0.0
    };

    // Combine residual fitting with lookahead anticipation
    let combined_bonus = if node_residual_cpu < mean_cpu_residual && node_residual_ram < mean_ram_residual {
        (residual_fit_bonus + lookahead_pack_bonus) / 2.0
    } else {
        residual_fit_bonus - lookahead_pack_bonus
    };

    let score = cpu_norm + ram_norm - imbalance_penalty + lookahead_bonus + combined_bonus - time_horizon_factor;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = (node_residual_cpu as f64 - job_cpu as f64) / node_capacity_cpu as f64;
    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / node_capacity_ram as f64;
    let imbalance = (cpu_norm - ram_norm).abs();

    let horizon_factor = 1.0 + (step_index as f64 / total_jobs as f64);
    let lookahead_factor = if next_job_cpu <= node_residual_cpu && next_job_ram <= node_residual_ram {
        2.0
    } else {
        1.0
    };

    let cpu_packing_bonus = node_capacity_cpu as f64 - (node_residual_cpu + job_cpu) as f64;
    let ram_packing_bonus = node_capacity_ram as f64 - (node_residual_ram + job_ram) as f64;
    let packing_bonus = cpu_packing_bonus * ram_packing_bonus;

    let imbalance_penalty = 1.0 / (imbalance + 1e-5); // Avoid division by zero

    let residual_ratio_cpu = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let residual_ratio_ram = node_residual_ram as f64 / node_capacity_ram as f64;

    let fine_grained_penalty = (residual_ratio_cpu - mean_cpu_residual).powi(2) + (residual_ratio_ram - mean_ram_residual).powi(2);

    let score = horizon_factor * imbalance.powi(2) * imbalance_penalty * lookahead_factor * packing_bonus - fine_grained_penalty;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
